// Miami Rice: generate everything that carries the palette from theme/miami-rice.json.
//   node scripts/theme.mjs          writes assets/css/tokens.css and theme/export/*
//   node scripts/theme.mjs --check  fails if the generated files are stale (for CI)
// No dependencies. Edit theme/miami-rice.json, never the generated files.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const T = JSON.parse(readFileSync(join(root, 'theme/miami-rice.json'), 'utf8'));
const FLAVOURS = Object.keys(T.flavours);
const check = process.argv.includes('--check');

// ---- colour: hex <-> OKLCH, with gamut mapping by chroma reduction (same method as the palette lab) ----
const toLin = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const fromLin = (c) => (c <= 0.0031308 ? c * 12.92 : 1.055 * c ** (1 / 2.4) - 0.055);
function hexToOklch(hex) {
  const [r, g, b] = [1, 3, 5].map((i) => toLin(parseInt(hex.slice(i, i + 2), 16) / 255));
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bb = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  return [L, Math.hypot(a, bb), ((Math.atan2(bb, a) * 180) / Math.PI + 360) % 360];
}
function oklchToLin(L, C, H) {
  const a = C * Math.cos((H * Math.PI) / 180), b = C * Math.sin((H * Math.PI) / 180);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s];
}
function oklchToHex(L, C, H) {
  let lo = 0, hi = C, rgb = oklchToLin(L, C, H);
  const inGamut = (v) => v.every((x) => x >= -1e-4 && x <= 1 + 1e-4);
  if (!inGamut(rgb)) {
    for (let i = 0; i < 30; i++) { const mid = (lo + hi) / 2; if (inGamut(oklchToLin(L, mid, H))) lo = mid; else hi = mid; }
    rgb = oklchToLin(L, lo, H);
  }
  return '#' + rgb.map((x) => Math.round(Math.min(1, Math.max(0, fromLin(Math.min(1, Math.max(0, x))))) * 255).toString(16).padStart(2, '0')).join('');
}
const lighten = (hex, dl = 0.05) => { const [L, C, H] = hexToOklch(hex); return oklchToHex(Math.min(0.92, L + dl), C, H); };

// ---- resolving a token name for a flavour ----
function resolve(name, f) {
  const fl = T.flavours[f];
  if (name.endsWith('+')) return lighten(resolve(name.slice(0, -1), f));
  if (T.accents[name]) return T.accents[name];
  if (T.neutrals[name]) return T.neutrals[name];
  if (fl[name]) return fl[name];
  throw new Error(`unknown token "${name}" in flavour ${f}`);
}
const ANSI_ORDER = ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white', 'brightBlack', 'brightRed', 'brightGreen', 'brightYellow', 'brightBlue', 'brightMagenta', 'brightCyan', 'brightWhite'];
function scheme(f) {
  const fl = T.flavours[f], t = T.terminal, R = (n) => resolve(n, f);
  return {
    name: `Miami Rice ${fl.label}`, background: R(t.background), foreground: R(t.foreground), cursor: R(t.cursor), cursorText: R(t.cursorText),
    selectionBackground: R(t.selectionBackground), selectionForeground: R(t.selectionForeground),
    ansi: ANSI_ORDER.map((k) => R(T.ansi[k])),
  };
}

// ---- outputs ----
const out = new Map();
const kebab = (s) => s.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
const GEN = 'Generated by scripts/theme.mjs from theme/miami-rice.json. Do not edit.';

// the blog: CSS custom properties, midnight by default, the other flavours by data-flavour on <html>
{
  const shared = [
    ...Object.entries(T.accents).map(([k, v]) => `  --${k}: ${v};`),
    ...Object.entries(T.neutrals).map(([k, v]) => `  --${k}: ${v};`),
    ...Object.entries(T.roles).map(([k, v]) => `  --${k}: var(--${v});`),
    ...Object.entries(T.syntax).map(([k, v]) => `  --sx-${k}: var(--${v});`),
    '  --glow: 32%;',
  ].join('\n');
  const flav = (f) => Object.entries(T.flavours[f]).filter(([k]) => !['hour', 'label', 'note'].includes(k)).map(([k, v]) => (k === 'glow' ? `  --sky: var(--${v});` : `  --${kebab(k)}: ${v};`)).join('\n');
  let css = `/* ${GEN} */\n:root {\n  color-scheme: dark;\n${shared}\n  /* flavour: ${T.flavours[FLAVOURS[0]].label} (default) */\n${flav(FLAVOURS[0])}\n}\n`;
  for (const f of FLAVOURS.slice(1)) css += `:root[data-flavour="${f}"] {\n  /* ${T.flavours[f].label}: ${T.flavours[f].note} */\n${flav(f)}\n}\n`;
  out.set('assets/css/tokens.css', css);
}

// Windows Terminal: one settings fragment holding all three schemes
out.set('theme/export/windows-terminal/miami-rice.json', JSON.stringify({
  $comment: 'Paste into the "schemes" array of settings.json, then set "colorScheme" on a profile.',
  schemes: FLAVOURS.map((f) => {
    const s = scheme(f), a = s.ansi;
    return { name: s.name, background: s.background, foreground: s.foreground, cursorColor: s.cursor, selectionBackground: s.selectionBackground,
      black: a[0], red: a[1], green: a[2], yellow: a[3], blue: a[4], purple: a[5], cyan: a[6], white: a[7],
      brightBlack: a[8], brightRed: a[9], brightGreen: a[10], brightYellow: a[11], brightBlue: a[12], brightPurple: a[13], brightCyan: a[14], brightWhite: a[15] };
  }),
}, null, 2) + '\n');

for (const f of FLAVOURS) {
  const s = scheme(f), a = s.ansi, slug = `miami-rice-${f}`;
  out.set(`theme/export/ghostty/${slug}`, `# ${s.name}\n` + [`background = ${s.background}`, `foreground = ${s.foreground}`, `cursor-color = ${s.cursor}`, `cursor-text = ${s.cursorText}`,
    `selection-background = ${s.selectionBackground}`, `selection-foreground = ${s.selectionForeground}`, ...a.map((c, i) => `palette = ${i}=${c}`)].join('\n') + '\n');
  out.set(`theme/export/alacritty/${slug}.toml`, `# ${s.name}\n[colors.primary]\nbackground = "${s.background}"\nforeground = "${s.foreground}"\n\n[colors.cursor]\ncursor = "${s.cursor}"\ntext = "${s.cursorText}"\n\n[colors.selection]\nbackground = "${s.selectionBackground}"\ntext = "${s.selectionForeground}"\n\n`
    + ['normal', 'bright'].map((g, gi) => `[colors.${g}]\n` + ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white'].map((n, i) => `${n} = "${a[gi * 8 + i]}"`).join('\n')).join('\n\n') + '\n');
  out.set(`theme/export/wezterm/${slug}.toml`, `# ${s.name}\n[metadata]\nname = "${s.name}"\n\n[colors]\nforeground = "${s.foreground}"\nbackground = "${s.background}"\ncursor_bg = "${s.cursor}"\ncursor_fg = "${s.cursorText}"\ncursor_border = "${s.cursor}"\nselection_bg = "${s.selectionBackground}"\nselection_fg = "${s.selectionForeground}"\n`
    + `ansi = [${a.slice(0, 8).map((c) => `"${c}"`).join(', ')}]\nbrights = [${a.slice(8).map((c) => `"${c}"`).join(', ')}]\n`);
  out.set(`theme/export/kitty/${slug}.conf`, `# ${s.name}\nbackground ${s.background}\nforeground ${s.foreground}\ncursor ${s.cursor}\ncursor_text_color ${s.cursorText}\nselection_background ${s.selectionBackground}\nselection_foreground ${s.selectionForeground}\n`
    + a.map((c, i) => `color${i} ${c}`).join('\n') + '\n');
}

let stale = 0;
for (const [path, body] of out) {
  const full = join(root, path);
  if (check) { if (!existsSync(full) || readFileSync(full, 'utf8') !== body) { console.error('stale:', path); stale++; } continue; }
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, body);
}
if (check) process.exit(stale ? 1 : 0);
console.log(`wrote ${out.size} files from theme/miami-rice.json`);
